import { useDialog } from "@lumeweb/portal-framework-ui";
import { Button, lazyIcon } from "@lumeweb/portal-framework-ui-core";
import { useUpdatePassword } from "@refinedev/core";

import { updatePasswordDialogConfig } from "@/ui/dialogs/updatePassword";

import { Card } from "@/ui/components/Card";
const Key = lazyIcon("Key");


export default function Password() {
  const { mutateAsync: updatePassword } = useUpdatePassword();
  const { openDialog } = useDialog();
  return (
    <Card
      border
      description="Manage your account password"
      icon={Key}
      title="Password">
      <div className="text-muted-foreground flex items-center gap-2 text-sm">
        <div className="flex gap-1">
          {Array.from({ length: 8 }).map((_, i) => (
            <div className="bg-muted h-2 w-2 rounded-full" key={i} />
          ))}
        </div>
        <span>••••••••</span>
      </div>
      <Button
        className="h-11 w-full whitespace-normal md:h-9 md:whitespace-nowrap"
        onClick={(e) => {
          e.preventDefault();
          openDialog(updatePasswordDialogConfig(updatePassword));
        }}>
        Change Password
      </Button>
    </Card>
  );
}
